<script setup>
import {computed,onBeforeUnmount,onMounted,reactive,ref,watch} from 'vue';
import {useSalesRuntime} from './sales-runtime.js';
import {receiptBlocks} from './sales-model.js';
import ReceiptCard from './ReceiptCard.vue';
import CatalogModal from '../catalog/CatalogModal.vue';
import '../catalog/catalog.css';
import './sales.css';
const vm=useSalesRuntime(),company=ref(''),productId=ref(''),design=ref(null),preview=ref(false),imageFile=ref(null),imageHash=ref(''),imageBusy=ref(false),imageUrl=ref(''),removeImage=ref(false),saved=ref('');
const draft=reactive({header:'',footer:'',color:'',order:[],text:''}),key=vm.key();let controller,revision=0,objectUrl='';
const admin=computed(()=>vm.identity.value?.account.type==='system'),mainId=computed(()=>admin.value?null:vm.identity.value?.account.type==='main_agent'?vm.ownId.value:null);
const companies=computed(()=>[...new Map(vm.state.options.products.map(product=>[product.provider_id,{id:product.provider_id,name:product.provider_name}])).values()]);
const products=computed(()=>vm.state.options.products.filter(product=>Number(product.provider_id)===Number(company.value))),product=computed(()=>products.value.find(product=>Number(product.id)===Number(productId.value)));
const editable=computed(()=>admin.value?vm.can('branding.receipt')&&vm.can('products.edit'):mainId.value&&vm.can('branding.edit'));
const previewReceipt=computed(()=>({product_name:product.value?.name,extra_fields:product.value?.extra_fields,design:design.value?{...design.value,...(admin.value?{header:draft.header,footer:draft.footer,color:draft.color,display_order:draft.order}:{agent_text:draft.text,agent_color:draft.color,agent_image:removeImage.value?null:imageUrl.value || design.value.agent_image})}:null}));
const dirty=computed(()=>JSON.stringify(draft)!==saved.value || imageFile.value || removeImage.value!==Boolean(design.value?.agent_image_removed));
function clearFile(){if(objectUrl)URL.revokeObjectURL(objectUrl);objectUrl='';imageFile.value=null;imageUrl.value='';imageHash.value='';}
async function loadLayout(){controller?.abort();controller=new AbortController();const expected=++revision;design.value=null;clearFile();vm.state.error='';if(!product.value)return;try{const response=await vm.api.layout(product.value.id,{},controller.signal);if(expected!==revision)return;design.value=response.data;Object.assign(draft,{header:design.value.header,footer:design.value.footer,color:admin.value?design.value.color:design.value.agent_color,order:[...design.value.display_order],text:design.value.agent_text});removeImage.value=Boolean(design.value.agent_image_removed);saved.value=JSON.stringify(draft);}catch(error){if(error.name!=='AbortError'&&expected===revision)vm.state.error=await vm.failure(error);}}
async function chooseImage(event){const file=event.target.files?.[0];event.target.value='';if(!file)return;imageBusy.value=true;try{if(!['image/png','image/jpeg'].includes(file.type)||file.size>700000)throw Error('اختر صورة PNG أو JPEG بحجم لا يتجاوز 700000 بايت.');const bitmap=await createImageBitmap(file);const valid=bitmap.width<=4096&&bitmap.height<=4096;bitmap.close();if(!valid)throw Error('أبعاد الصورة يجب ألا تتجاوز 4096 بكسل.');const digest=await crypto.subtle.digest('SHA-256',await file.arrayBuffer());clearFile();imageHash.value=Array.from(new Uint8Array(digest),byte=>byte.toString(16).padStart(2,'0')).join('');imageFile.value=file;objectUrl=URL.createObjectURL(file);imageUrl.value=objectUrl;removeImage.value=false;}catch(error){vm.state.error=error.message;}finally{imageBusy.value=false;}}
function remove(){clearFile();removeImage.value=true;}
function move(index,direction){const next=index+direction;if(next<0||next>=draft.order.length)return;[draft.order[index],draft.order[next]]=[draft.order[next],draft.order[index]];}
async function save(){if(!editable.value||!design.value||imageBusy.value)return;const layout=admin.value?{header:draft.header,footer:draft.footer,color:draft.color,display_order:[...draft.order]}:{agent_text:draft.text,agent_color:draft.color,agent_image_removed:removeImage.value};const payload={version:admin.value?design.value.version:design.value.personal_version,layout,...(!admin.value?{account_id:Number(mainId.value)}:{})};
  // Include the file identity in the client retry key; the server verifies the actual file hash.
  const identity={...payload,image_hash:imageHash.value || null};const result=await vm.execute(identity,key,(_value,signal)=>vm.api.saveLayout(product.value.id,{...payload,idempotency_key:_value.idempotency_key},signal,imageFile.value),'تم حفظ تصميم هذه الفئة.');if(result)await loadLayout();}
watch(company,()=>{productId.value=products.value[0]?.id || '';});watch(productId,loadLayout);
onMounted(async()=>{await vm.load(true);company.value=companies.value[0]?.id || '';});onBeforeUnmount(()=>{revision++;controller?.abort();clearFile();design.value=null;});
</script>
<template><div class="catalog-workspace sales-workspace"><p v-if="vm.state.error" class="notice warn" role="alert">{{vm.state.error}}</p><p v-if="vm.state.notice" class="notice" role="status">{{vm.state.notice}}</p><section class="simple-card-workspace"><div class="card"><div class="simple-card-heading"><h3>تصميم البطاقة</h3><div class="simple-card-selectors"><label>الشركة<select v-model="company" aria-label="شركة البطاقة"><option v-for="provider in companies" :key="provider.id" :value="provider.id">{{provider.name}}</option></select></label><label>الفئة<select v-model="productId" aria-label="فئة البطاقة"><option v-for="category in products" :key="category.id" :value="category.id">{{category.name}}</option></select></label></div></div></div><div v-if="product && design" class="two simple-card-designer"><form class="card simple-card-controls" @submit.prevent="save"><fieldset :disabled="!editable || vm.state.busy || imageBusy"><template v-if="admin"><label>النص العلوي<textarea v-model="draft.header" maxlength="1000" rows="2"></textarea></label><label>النص السفلي<textarea v-model="draft.footer" maxlength="1000" rows="2"></textarea></label><label class="personal-card-color">لون النص<input v-model="draft.color" type="color"></label><h3>ترتيب البطاقة</h3><div class="card-order-list"><div v-for="(block,index) in draft.order" :key="block" class="card-order-row"><span>{{receiptBlocks[block]}}</span><div class="actions"><button type="button" class="btn small" :disabled="index===0" :aria-label="`رفع ${receiptBlocks[block]}`" @click="move(index,-1)">↑</button><button type="button" class="btn small" :disabled="index===draft.order.length-1" :aria-label="`تنزيل ${receiptBlocks[block]}`" @click="move(index,1)">↓</button></div></div></div></template><template v-else><h3>صورتي على البطاقة</h3><div class="attachment-field"><label class="btn small">{{imageBusy?'جارٍ تجهيز الصورة':'إضافة صورة (اختياري)'}}<input type="file" accept="image/png,image/jpeg" hidden @change="chooseImage"></label><div v-if="!removeImage && (imageUrl || design.agent_image)" class="attachment-preview"><img :src="imageUrl || design.agent_image" alt="معاينة صورة الوكيل"><button type="button" class="btn small" @click="remove">إزالة</button></div></div><label>نصي على البطاقة<textarea v-model="draft.text" maxlength="1000" rows="3"></textarea></label><label class="personal-card-color">لون الخط<input v-model="draft.color" type="color"></label></template></fieldset><div class="formfoot"><button type="button" class="btn" :disabled="imageBusy || !product" @click="preview=true">معاينة البطاقة</button><button class="btn primary" :disabled="!editable || vm.state.busy || imageBusy || !dirty">حفظ التعديلات</button></div></form><div class="card simple-card-preview"><h3>معاينة البطاقة</h3><ReceiptCard :receipt="previewReceipt" preview/></div></div><div v-else class="card empty">{{vm.state.loading?'جارٍ تحميل التصميم…':'لا توجد فئات متاحة'}}</div></section><CatalogModal v-if="preview && design" title="معاينة البطاقة" section="تصميم البطاقة" content-class="sales-modal" @close="preview=false"><ReceiptCard :receipt="previewReceipt" preview/></CatalogModal></div></template>
